      context->CheckPermission(requesting_origin, embedding_origin);
  if (permission_result != content::ChooserContextBase::PermissionResult::GRANTED) {
    return results;
  }

  content::WebsiteSettingsUserSettings* settings = context->GetWebsiteSettings();
